export type ParsedClaimFeesInstruction<
  TProgram extends string = typeof INDEX_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    claimer: TAccountMetas[0];
    config: TAccountMetas[1];
    index: TAccountMetas[2];
    shareMint: TAccountMetas[3];
    recipientShareAta: TAccountMetas[4];
    /** Required for `FeeKind::Parent`. */
    parentIndex?: TAccountMetas[5] | undefined;
    tokenProgram: TAccountMetas[6];
  };
  data: ClaimFeesInstructionData;
};

export function parseClaimFeesInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimFeesInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === INDEX_VAULT_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      claimer: getNextAccount(),
      config: getNextAccount(),
      index: getNextAccount(),
      shareMint: getNextAccount(),
      recipientShareAta: getNextAccount(),
      parentIndex: getNextOptionalAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getClaimFeesInstructionDataDecoder().decode(instruction.data),
  };
}
